import { View, Text, Platform, useWindowDimensions } from "react-native";

// Hàm thuần: dễ kiểm thử, tách khỏi giao diện
const layoutFor = (width) => (width >= 768 ? "tablet" : "phone");

export default function App() {
  const { width } = useWindowDimensions();       // tự cập nhật khi xoay màn hình
  const font = Platform.select({ ios: 17, android: 16, default: 16 });
  return (
    <View>
      <Text testID="os">{Platform.OS}</Text>
      <Text testID="layout">{layoutFor(width)}</Text>
      <Text style={{ fontSize: font }}>Văn bản</Text>
    </View>
  );
}

