import { Text } from "react-native";

function columnsFor(width) {
  return width < 500 ? 1 : width < 900 ? 2 : 3;
}

export default function App() {
  return <Text testID="c">{[columnsFor(320), columnsFor(600), columnsFor(1200)].join(",")}</Text>;
}

